css:
:where(.wtyg-map-site_circus) *{margin: 0; padding: 0; box-sizing: border-box;}
:where(.wtyg-map-site_circus){background: #0a0a0a; overflow: hidden;}
:where(.wtyg-map-site_circus) :is([data-wtyg-id="circus-map-container"],#wtyg-noid-circus-map-container) *{box-sizing:border-box}
:where(.wtyg-map-site_circus) .circus-overlay{position:absolute;top:0;left:0;right:0;z-index:1000;background:linear-gradient(180deg,rgba(45,52,54,0.95) 0%,rgba(45,52,54,0.7) 70%,transparent 100%);padding:1.5rem 2rem 3rem;pointer-events:none}
:where(.wtyg-map-site_circus) .circus-header{display:flex;justify-content:space-between;align-items:flex-start;gap:1.5rem;flex-wrap:wrap}
:where(.wtyg-map-site_circus) .circus-title h1{font-family:"Cormorant Garamond",serif;font-size:2.5rem;font-weight:300;margin:0 0 0.5rem 0;color:#f5f5f0}
:where(.wtyg-map-site_circus) .circus-title p{font-size:0.85rem;color:#d4a574;letter-spacing:0.05em;text-transform:uppercase;font-weight:300;margin:0}
:where(.wtyg-map-site_circus) .circus-filters{pointer-events:auto;display:flex;gap:0.5rem;flex-wrap:wrap}
:where(.wtyg-map-site_circus) .circus-btn{background:rgba(255,255,255,0.08);border:1px solid rgba(255,255,255,0.15);color:#f5f5f0;padding:0.5rem 1rem;border-radius:2rem;font-size:0.8rem;cursor:pointer;transition:all 0.3s;font-family:"Work Sans",sans-serif}
:where(.wtyg-map-site_circus) .circus-btn:hover{background:rgba(255,255,255,0.15);transform:translateY(-2px)}
:where(.wtyg-map-site_circus) .circus-btn.active{background:#d4a574;color:#2d3436;font-weight:500}
:where(.wtyg-map-site_circus) .circus-stats{position:absolute;bottom:1.5rem;left:2rem;z-index:1000;background:rgba(45,52,54,0.9);border:1px solid rgba(255,255,255,0.1);border-radius:1rem;padding:1rem 1.5rem}
:where(.wtyg-map-site_circus) .circus-num{font-family:"Cormorant Garamond",serif;font-size:1.8rem;font-weight:600;color:#d4a574;margin:0}
:where(.wtyg-map-site_circus) .circus-label{font-size:0.75rem;color:#f5f5f0;opacity:0.8;text-transform:uppercase;margin:0}
:where(.wtyg-map-site_circus) .leaflet-popup-content-wrapper{background:rgba(45,52,54,0.98)!important;border:1px solid rgba(255,255,255,0.15)!important;border-radius:1rem!important}
:where(.wtyg-map-site_circus) .leaflet-popup-tip{background:rgba(45,52,54,0.98)!important}
:where(.wtyg-map-site_circus) .circus-popup{padding:1.5rem;color:#f5f5f0}
:where(.wtyg-map-site_circus) .circus-cat{display:inline-block;font-size:0.65rem;font-weight:500;letter-spacing:0.1em;text-transform:uppercase;color:#d4a574;background:rgba(212,165,116,0.15);padding:0.25rem 0.75rem;border-radius:1rem;margin-bottom:0.5rem}
:where(.wtyg-map-site_circus) .circus-name{font-family:"Cormorant Garamond",serif;font-size:1rem;font-weight:600;margin:0.5rem 0}
:where(.wtyg-map-site_circus) .circus-addr{font-size:0.8rem;opacity:0.7;margin:0.25rem 0}
:where(.wtyg-map-site_circus) .circus-country{font-size:0.85rem;color:#d4a574;font-weight:500;margin-top:0.5rem}
:where(.wtyg-map-site_circus) .marker-circus{background:#e74c3c!important}
:where(.wtyg-map-site_circus) .marker-marine{background:#3498db!important}
:where(.wtyg-map-site_circus) .marker-dolphin{background:#9b59b6!important}
@media(max-width:768px){:where(.wtyg-map-site_circus) .circus-title h1{font-size:1.8rem}
:where(.wtyg-map-site_circus) .circus-header{flex-direction:column;gap:1rem}
:where(.wtyg-map-site_circus) .circus-stats{left:1rem;bottom:1rem;padding:0.75rem 1rem}}
